// 时间/Action完整业务字段。wrapper与同job预算由存读owner接，不重写这些业务字段。
#pragma once
#include "exact_struct_codec.hpp"
#include "work_period_codec_fields.hpp"
#include "fixed_service_history.hpp"
#include <charconv>
namespace hanmo::resident::time_fields {
using namespace exact_fields;
template<class C>Status transition_ref(C& c,FixedServiceTransitionRef& value){
 required_ref(c,"transition_id",value.transition_id);c.field("source_schema",value.source_schema);
 if(c.status().ok&&value.source_schema!=1)return c.reject("UnsupportedFixedTransitionSchema");
 return c.status();
}
inline const StableId& elapsed_action_ref(const ActionElapsedStore::Entry& value){return std::visit([](const auto& entry)->const StableId&{return entry.action_ref;},value);}
// Timing只允许原三个有限状态；Suspended与Terminal的真实业务来源留给owner反读。
template<class C> Status timing(C& c,ElapsedTiming& v){Integer tag=static_cast<Integer>(v.index());finite(c,"tag",tag,2);if(!c.status().ok)return c.status();if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<ElapsedRunning>(c).ok)return c.status();v=ElapsedRunning{};}else if(tag==1){if(!prepare_checkpoint_default_values<ElapsedSuspended>(c).ok)return c.status();v=ElapsedSuspended{};}else {if(!prepare_checkpoint_default_values<ElapsedTerminal>(c).ok)return c.status();v=ElapsedTerminal{};}}if(tag==0)return c.object("completion_due_at",[&](auto& x){return moment(x,std::get<ElapsedRunning>(v).completion_due_at);});if(tag==1)return required_ref(c,"reason_source_ref",std::get<ElapsedSuspended>(v).reason_source_ref);return required_ref(c,"outcome_ref",std::get<ElapsedTerminal>(v).outcome_ref);}
// Fixed完整声明序，不增加remaining或第二累计；正required仍原checked整数范围。
template<class C> Status elapsed_payload(C& c,ActionElapsedState& v){required_ref(c,"action_ref",v.action_ref);required_ref(c,"execution_source_ref",v.execution_source_ref);required_ref(c,"duration_definition_ref",v.duration_definition_ref);c.object("started_at",[&](auto& x){return moment(x,v.started_at);});c.object("required_units",[&](auto& x){return work_units(x,v.required_units);});c.object("credited_units",[&](auto& x){return work_units(x,v.credited_units);});c.object("last_settled_at",[&](auto& x){return moment(x,v.last_settled_at);});c.object("timing",[&](auto& x){return timing(x,v.timing);});c.field("owner_work_remainder",v.owner_work_remainder);required_ref(c,"owner_cost_state_ref",v.owner_cost_state_ref);if(!c.status().ok)return c.status();auto encoded=take(encode_canonical_fraction(v.required_units.value));Integer required=0;auto parsed=std::from_chars(encoded.numerator.data(),encoded.numerator.data()+encoded.numerator.size(),required);if(encoded.denominator!="1"||parsed.ec!=std::errc{}||parsed.ptr!=encoded.numerator.data()+encoded.numerator.size()||required<=0)return c.reject("InvalidFixedRequiredUnits");if(v.owner_work_remainder<0)return c.reject("InvalidOwnerWorkRemainder");if(take(compare_fractions(v.credited_units.value,v.required_units.value))>0)return c.reject("FixedElapsedCreditOverflow");if(take(compare_world_moments(v.started_at,v.last_settled_at))>0)return c.reject("InvalidFixedElapsedTimeOrder");return c.status();}
// 外层action_ref必须和同一原Action的Fixed或SharedWork payload相等，未选分支由完整owner准入核验。
template<class C> Status entry(C& c,ActionElapsedStore::Entry& v){StableId decoded_action;StableId& action=c.reading()?decoded_action:std::visit([](auto& entry)->StableId&{return entry.action_ref;},v);required_ref(c,"action_ref",action);Integer tag=v.index();finite(c,"timing_kind",tag,1);if(!c.status().ok)return c.status();if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<ActionElapsedState>(c).ok)return c.status();v=ActionElapsedState{};}else {if(!prepare_checkpoint_default_values<SharedWorkElapsedState>(c).ok)return c.status();v=SharedWorkElapsedState{};}}c.object("payload",[&](auto& x)->Status{if(tag==0)return elapsed_payload(x,std::get<ActionElapsedState>(v));auto& shared=std::get<SharedWorkElapsedState>(v);return work_fields::shared(x,shared);});if(c.status().ok&&c.reading()&&tag==1){std::get<SharedWorkElapsedState>(v).action_ref.swap(decoded_action);return c.status();}if(c.status().ok&&action!=elapsed_action_ref(v))return c.reject("ElapsedActionBindingMismatch");return c.status();}
// 时间来源不由start+H推算；MomentOwner与OriginalPeriod完整分支只存原真实ref。
template<class C> Status time_source(C& c,ElapsedTimeSource& value){Integer tag=static_cast<Integer>(value.index());finite(c,"tag",tag,1);if(!c.status().ok)return c.status();if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<MomentOwnerSource>(c).ok)return c.status();value=MomentOwnerSource{};}else {if(!prepare_checkpoint_default_values<OriginalPeriodSource>(c).ok)return c.status();value=OriginalPeriodSource{};}}return std::visit([&](auto& v){c.object("source_ref",[&](auto& x){return source(x,v.source_ref);});schema(c,"source_schema",v.source_schema);if constexpr(std::is_same_v<std::decay_t<decltype(v)>,OriginalPeriodSource>){c.field("processed_tick",v.processed_tick);if(c.status().ok&&v.processed_tick<0)return c.reject("InvalidOriginalPeriodTick");}return c.status();},value);}
// Terminal摘要保完整身份/两来源/结果，gate字段仍存在但本Fixed profile必须为空。
template<class C> Status terminal(C& c,ActionElapsedTerminalBinding& v){required_ref(c,"action_ref",v.action_ref);required_ref(c,"action_kind",v.action_kind);required_ref(c,"actor_id",v.actor_id);references(c,"participant_actor_ids",v.participant_actor_ids);c.object("original_execution_source_ref",[&](auto& x){return source(x,v.original_execution_source_ref);});finite(c,"timing_kind",v.timing_kind,1);c.object("started_source_ref",[&](auto& x){return time_source(x,v.started_source_ref);});c.object("ended_source_ref",[&](auto& x){return time_source(x,v.ended_source_ref);});required_ref(c,"terminal_result_ref",v.terminal_result_ref);optional_ref(c,"last_closed_gate_result_ref",v.last_closed_gate_result_ref);references(c,"retained_gate_result_refs",v.retained_gate_result_refs);if(c.status().ok&&v.timing_kind==0&&(v.last_closed_gate_result_ref||!v.retained_gate_result_refs.empty()))return c.reject("FixedElapsedUnexpectedGateResults");return c.status();}
// 历史cause有限四tag，原独立业务schema不与SourceRef合并或从physical版猜测。
template<class C> Status cause(C& c,FixedServiceTransitionCause& value){Integer tag=static_cast<Integer>(value.index());finite(c,"tag",tag,3);if(!c.status().ok)return c.status();if(c.reading()){switch(tag){case 0:{if(!prepare_checkpoint_default_values<FixedOwnerAdopted>(c).ok)return c.status();value=FixedOwnerAdopted{};}break;case 1:{if(!prepare_checkpoint_default_values<FixedOwnerStateChanged>(c).ok)return c.status();value=FixedOwnerStateChanged{};}break;case 2:{if(!prepare_checkpoint_default_values<FixedEligibilityChanged>(c).ok)return c.status();value=FixedEligibilityChanged{};}break;case 3:{if(!prepare_checkpoint_default_values<FixedOwnerTerminated>(c).ok)return c.status();value=FixedOwnerTerminated{};}break;}}return std::visit([&](auto& v){using T=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<T,FixedOwnerAdopted>||std::is_same_v<T,FixedOwnerStateChanged>){c.object("owner_source_ref",[&](auto& x){return source(x,v.owner_source_ref);});schema(c,"owner_source_schema",v.owner_source_schema);if constexpr(std::is_same_v<T,FixedOwnerStateChanged>)required_ref(c,"transition_rule_ref",v.transition_rule_ref);}else if constexpr(std::is_same_v<T,FixedEligibilityChanged>){c.object("original_cause_ref",[&](auto& x){return source(x,v.original_cause_ref);});schema(c,"original_cause_schema",v.original_cause_schema);required_ref(c,"transition_rule_ref",v.transition_rule_ref);required_ref(c,"original_owner_execution_ref",v.original_owner_execution_ref);}else{c.object("owner_result_ref",[&](auto& x){return source(x,v.owner_result_ref);});schema(c,"owner_result_schema",v.owner_result_schema);}return c.status();},value);}
// Fixed输入只能为原AppliedSource或锁内规则，禁止未知tag的默认成功分支。
template<class C> Status input(C& c,FixedServiceInputRef& value){Integer tag=static_cast<Integer>(value.index());finite(c,"tag",tag,1);if(!c.status().ok)return c.status();if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<FixedAppliedInput>(c).ok)return c.status();value=FixedAppliedInput{};}else {if(!prepare_checkpoint_default_values<FixedLockedRuleInput>(c).ok)return c.status();value=FixedLockedRuleInput{};}}return std::visit([&](auto& v){using T=std::decay_t<decltype(v)>;if constexpr(std::is_same_v<T,FixedAppliedInput>){c.object("source_ref",[&](auto& x){return source(x,v.source_ref);});schema(c,"source_schema",v.source_schema);}else{c.object("catalog_identity",[&](auto& x){return catalog(x,v.catalog_identity);});required_ref(c,"rule_ref",v.rule_ref);}return c.status();},value);}
// 同一完整输入ref只能出现一次；直接比较既有typed字段，不复制规范键或持久第二来源。
template<class C> Status inputs(C& c,const char* key,std::vector<FixedServiceInputRef>& values){auto s=c.sequence(key,values,[](auto& x,auto& value){return input(x,value);});if(!s.ok)return s;for(std::size_t i=0;i<values.size();++i)for(std::size_t j=0;j<i;++j)if(same_fixed_input_ref(values[i],values[j]))return c.reject("DuplicateFixedServiceInput",key);return c.status();}
// 完整0524第五根行；credited_at只是历史读值，解码不会将其加回当前entry。
template<class C> Status transition(C& c,FixedServiceTransition& v){required_ref(c,"transition_id",v.transition_id);c.field("source_schema",v.source_schema);if(c.status().ok&&v.source_schema!=1)return c.reject("UnsupportedFixedTransitionSchema");required_ref(c,"action_ref",v.action_ref);c.field("transition_ordinal",v.transition_ordinal);optional_ref(c,"previous_transition_ref",v.previous_transition_ref);Integer kind=static_cast<Integer>(v.kind);finite(c,"kind",kind,4);if(c.status().ok&&c.reading())v.kind=static_cast<FixedTransitionKind>(kind);c.object("occurred_at",[&](auto& x){return moment(x,v.occurred_at);});c.object("credited_at",[&](auto& x){return work_units(x,v.credited_at);});c.object("execution_source_ref",[&](auto& x){return source(x,v.execution_source_ref);});schema(c,"execution_source_schema",v.execution_source_schema);c.object("cause",[&](auto& x){return cause(x,v.cause);});inputs(c,"input_basis_refs",v.input_basis_refs);inputs(c,"previous_input_basis_refs",v.previous_input_basis_refs);c.optional("terminal_disposition",v.terminal_disposition,[](auto& x,auto& disposition){Integer tag=static_cast<Integer>(disposition);finite(x,"value",tag,3);if(x.status().ok&&x.reading())disposition=static_cast<FixedTerminalDisposition>(tag);return x.status();});if(!c.status().ok)return c.status();if(v.transition_ordinal<0)return c.reject("InvalidFixedTransitionOrdinal");const auto tag=v.cause.index();if(kind==0){if(v.transition_ordinal!=0||v.previous_transition_ref||!v.previous_input_basis_refs.empty()||tag!=0||take(compare_fractions(v.credited_at.value,CanonicalFraction{}))!=0)return c.reject("InvalidFixedStartedTransition");}else if(v.transition_ordinal==0||!v.previous_transition_ref)return c.reject("InvalidFixedTransitionPredecessor");if(kind==4){if(!v.terminal_disposition||tag!=3||!v.input_basis_refs.empty())return c.reject("InvalidFixedTerminalTransition");}else if(v.terminal_disposition||(kind!=0&&tag!=1&&tag!=2))return c.reject("InvalidFixedTransitionCause");return c.status();}
// world_timeline/2只有version→state，Common.tick不在这里重复编码。
template<class C> Status timeline(C& c,WorldTimelineState& v){Integer version=2;c.field("version",version);if(c.status().ok&&version!=2)return c.reject("UnsupportedWorldTimelineVersion");c.object("state",[&](auto& x){x.object("scale_ref",[&](auto& s){required_ref(s,"definition_id",v.scale_ref.definition_id);s.field("version",v.scale_ref.version);s.field("units_per_half_day",v.scale_ref.units_per_half_day);if(s.status().ok&&(v.scale_ref.version<=0||v.scale_ref.units_per_half_day<=0))return s.reject("InvalidTimeScaleRef");return s.status();});x.object("sub_half_day",[&](auto& s){return fraction(s,v.sub_half_day);});required_ref(x,"period_id",v.period_id);optional_ref(x,"opening_receipt_ref",v.opening_receipt_ref);optional_ref(x,"close_receipt_ref",v.close_receipt_ref);Integer tag=static_cast<Integer>(v.boundary_state);finite(x,"boundary_state",tag,1);if(x.status().ok&&x.reading())v.boundary_state=static_cast<PeriodBoundaryState>(tag);if(x.status().ok){take(encode_world_moment({0,v.sub_half_day}));if(tag==0&&take(compare_fractions(v.sub_half_day,CanonicalFraction{}))!=0)return x.reject("ReadyTimelineNotBoundary");}return x.status();});return c.status();}
// 五根始终出现；真实gate结果随SharedWork分支读取，entries/终局/action历史ID各自唯一。
template<class C> Status elapsed(C& c,ActionElapsedStore& v){Integer version=2;c.field("version",version);if(c.status().ok&&version!=2)return c.reject("UnsupportedActionElapsedVersion");std::size_t entry_position=0;c.sequence("entries",v.entries,[&](auto& x,auto& y){auto s=entry(x,y);if(s.ok)for(std::size_t i=0;i<entry_position;++i)if(elapsed_action_ref(v.entries[i])==elapsed_action_ref(y))return x.reject("DuplicateElapsedAction");++entry_position;return s;});c.sequence("gate_results",v.gate_results,[](auto& x,auto& result){return work_fields::result(x,result);});std::size_t terminal_position=0;c.sequence("terminal_bindings",v.terminal_bindings,[&](auto& x,auto& y){auto s=terminal(x,y);if(s.ok)for(std::size_t i=0;i<terminal_position;++i)if(v.terminal_bindings[i].action_ref==y.action_ref)return x.reject("DuplicateElapsedTerminalBinding");++terminal_position;return s;});std::size_t transition_position=0;c.sequence("fixed_service_transitions",v.fixed_service_transitions,[&](auto& x,auto& y){auto s=transition(x,y);if(s.ok)for(std::size_t i=0;i<transition_position;++i){const auto& previous=v.fixed_service_transitions[i];if(previous.transition_id==y.transition_id||(previous.action_ref==y.action_ref&&previous.transition_ordinal==y.transition_ordinal))return x.reject("DuplicateFixedServiceTransition");}++transition_position;return s;});return c.status();}

}
